#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("BALANCED\n");
        return 0;
    }
    char *str = argv[1];
    int len = strlen(str);
    int stack[1000];
    int top = 0;
    for (int i = 0; i < len; i++) {
        if (str[i] == '(' || str[i] == '[' || str[i] == '{') {
            stack[top++] = str[i];
        } else if (str[i] == ')' || str[i] == ']' || str[i] == '}') {
            if (top == 0) {
                printf("UNBALANCED\n");
                return 0;
            }
            char c = stack[--top];
            if ((str[i] == ')' && c != '(') || (str[i] == ']' && c != '[') || (str[i] == '}' && c != '{')) {
                printf("UNBALANCED\n");
                return 0;
            }
        }
    }
    if (top == 0) {
        printf("BALANCED\n");
    } else {
        printf("UNBALANCED\n");
    }
    return 0;
}
